"use client";

import type { FormEvent } from "react";
import { useRouter } from "next/navigation";
import { useState } from "react";

type ErrorResponse = {
  error?: string;
};

export function InquiryForm() {
  const router = useRouter();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setIsSubmitting(true);
    setMessage(null);

    const form = event.currentTarget;
    const formData = new FormData(form);

    try {
      const response = await fetch("/api/inquiries", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          company: formData.get("company"),
          rawText: formData.get("rawText"),
        }),
      });

      if (!response.ok) {
        const data = (await response.json()) as ErrorResponse;
        throw new Error(data.error || "Nie udało się zapisać zapytania.");
      }

      form.reset();
      setMessage("Zapytanie zostało zapisane.");
      router.refresh();
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Nie udało się zapisać zapytania.",
      );
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Firma (opcjonalnie)
        <input name="company" type="text" maxLength={200} />
      </label>

      <label>
        Treść RFQ
        <textarea name="rawText" rows={10} maxLength={50_000} required />
      </label>

      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? "Zapisywanie…" : "Zapisz zapytanie"}
      </button>

      {message && <p role="status">{message}</p>}
    </form>
  );
}
